#include <atomic>
#include <thread>
#include <vector>

// Runs f(i) on n threads; an exception in any thread fails the test (instead of std::terminate).
template <typename F>
static void run_threads(int n, F f) {
  std::atomic<bool> failed{false};
  std::vector<std::thread> threads;
  for (int i = 0; i < n; ++i)
    threads.emplace_back([&, i] {
      try {
        f(i);
      } catch (...) {
        failed = true;
      }
    });
  for (auto& t : threads) t.join();
  if (failed) throw cl::Failure{"a thread threw an exception"};
}

TEST("deposit and withdraw") {
  Account a(100);
  a.deposit(50);
  CHECK(a.withdraw(30));
  CHECK_EQ(a.balance(), 120L);
}

TEST("withdraw refuses to overdraw") {
  Account a(10);
  CHECK(!a.withdraw(11));
  CHECK_EQ(a.balance(), 10L);
}

TEST("concurrent deposits are not lost") {
  Account a(0);
  run_threads(8, [&](int) {
    for (int i = 0; i < 20000; ++i) a.deposit(1);
  });
  CHECK_EQ(a.balance(), 160000L);
}

TEST("transfer moves money") {
  Account a(100), b(0);
  CHECK(transfer(a, b, 40));
  CHECK_EQ(a.balance(), 60L);
  CHECK_EQ(b.balance(), 40L);
}

TEST("a transfer that can't be covered changes nothing") {
  Account a(10), b(5);
  CHECK(!transfer(a, b, 11));
  CHECK_EQ(a.balance(), 10L);
  CHECK_EQ(b.balance(), 5L);
}

TEST("opposite transfers at once: no deadlock, no money created") {
  Account a(1000), b(1000);
  run_threads(4, [&](int i) {
    for (int k = 0; k < 5000; ++k) {
      if (i % 2 == 0) transfer(a, b, 1);
      else transfer(b, a, 1);
    }
  });
  CHECK_EQ(a.balance() + b.balance(), 2000L);
}

TEST("transfer to the same account") {
  Account a(50);
  CHECK(transfer(a, a, 20));
  CHECK_EQ(a.balance(), 50L);
}

