#include <mutex>

class Account {
 public:
  explicit Account(long balance) : balance_(balance) {}

  long balance() const {
    std::lock_guard lock(m_);
    return balance_;
  }

  void deposit(long amount) {
    std::lock_guard lock(m_);
    balance_ += amount;
  }

  bool withdraw(long amount) {
    std::lock_guard lock(m_);
    if (amount > balance_) return false;
    balance_ -= amount;
    return true;
  }

  friend bool transfer(Account& from, Account& to, long amount);

 private:
  mutable std::mutex m_;  // mutable: balance() is const but still has to lock
  long balance_;
};

bool transfer(Account& from, Account& to, long amount) {
  if (&from == &to) return true;  // locking the same std::mutex twice would deadlock (it's UB)
  // std::scoped_lock locks several mutexes using a deadlock-avoidance algorithm,
  // so transfer(a, b) and transfer(b, a) running together can't each hold one lock
  // and wait for the other.
  std::scoped_lock lock(from.m_, to.m_);
  if (amount > from.balance_) return false;
  from.balance_ -= amount;
  to.balance_ += amount;
  return true;
}
